 private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
 private void menu(){Ui.menu(this,findViewById(android.R.id.content),new String[]{"Arquivos lembrados","Trechos favoritos","Todos os resultados","Preparar voz por Wi-Fi","Como funciona"},new String[]{"Gerenciar arquivos lembrados","Buscar trechos marcados como favoritos","Buscar em toda a memória","Baixar modelo de reconhecimento local por Wi-Fi","Como funciona a memória"},new Runnable[]{this::sources,()->{favorites=true;search();},()->{favorites=false;search();},this::prepare,()->dialog=new AlertDialog.Builder(this).setTitle("Memória no celular").setMessage("A busca usa palavras e prefixos, não compreensão semântica. Digite as palavras que espera encontrar. O microfone usa o serviço de voz do Android.\n\nPDFs precisam de texto extraível. Imagens não recebem OCR em lote. SRT/VTT precisam corresponder ao arquivo selecionado.\n\nTranscrição local é opcional, usa modelo de 60 MB e depende de RAM e codecs. Horários são aproximados (janelas de até 20 s); confirme antes de recortar. Pode errar, especialmente em música.\n\nA análise continua minimizada, é cancelável e não envia seus arquivos a um servidor. Se o Android encerrar o processo, solicite novamente. Resultados ficam no armazenamento privado. Reindexe após editar arquivos. Remover memória não apaga os originais. Salvar favoritos permite reencontrar trechos indexados.").setPositiveButton("Entendi",null).show()});}
 private void add(){dialog=new AlertDialog.Builder(this).setTitle("Adicionar à memória").setItems(new String[]{"PDF com texto","Vídeo/áudio com legenda SRT ou VTT","Transcrever fala de vídeo ou áudio"},(d,i)->pick(i==0?PDF:i==1?OWNER:SPEECH)).setNegativeButton("Cancelar",null).show();}
 private void pick(int request){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(request==PDF?"application/pdf":"*/*").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);if(request==OWNER||request==SPEECH)i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"audio/*","video/*"});try{startActivityForResult(i,request);}catch(ActivityNotFoundException error){status.setText("Seletor de arquivos indisponível neste celular.");}}
 private void keep(Intent data){try{if((data.getFlags()&Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION)!=0)getContentResolver().takePersistableUriPermission(data.getData(),Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(RuntimeException ignored){}}
 static String name(Context c,Uri uri){try(Cursor q=c.getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(q!=null&&q.moveToFirst())return q.getString(0);}catch(RuntimeException ignored){}return uri.getLastPathSegment()==null?"Arquivo":uri.getLastPathSegment();}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==VoiceSearch.REQUEST){String said=VoiceSearch.result(result,data);if(!said.isEmpty()){query.setText(said);search();}return;}if(result!=RESULT_OK||data==null||data.getData()==null)return;keep(data);Uri uri=data.getData();if(request==OWNER){owner=uri;ownerName=name(this,uri);pick(SUBTITLE);}else if(request==SUBTITLE&&owner!=null)start(owner,uri,ownerName+" • "+name(this,uri),getContentResolver().getType(owner)!=null&&getContentResolver().getType(owner).startsWith("audio/")?"subtitle_audio":"subtitle");else if(request==PDF)start(uri,null,name(this,uri),"pdf");else if(request==SPEECH){String mime=getContentResolver().getType(uri);start(uri,null,name(this,uri),mime!=null&&mime.startsWith("audio/")?"audio":"speech");}}
 private void start(Uri uri,Uri side,String name,String kind){if(MemoryIndexService.running){status.setText("Aguarde a análise atual ou cancele antes de iniciar outra.");return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},865);worker.execute(()->{MemoryStore.Source source=MemoryStore.source(this,uri,side,name,kind);main.post(()->{if(isDestroyed())return;try{if(!MemoryIndexService.start(this,source,false))status.setText("Há outra análise em andamento.");else{job.setText("Iniciando análise…");cancel.setVisibility(View.VISIBLE);}}catch(RuntimeException error){status.setText("Não foi possível iniciar a análise. Abra o arquivo novamente pelo Android.");}});});}
 private void prepare(){dialog=new AlertDialog.Builder(this).setTitle("Preparar voz local").setMessage("Baixa cerca de 60 MB por Wi-Fi. O modelo fica no celular. A transcrição usa processamento e bateria somente quando solicitada; aparelhos com pouca RAM podem não conseguir executá-la.").setPositiveButton("Preparar",(d,w)->{try{if(!MemoryIndexService.start(this,null,true))status.setText("Aguarde ou cancele a análise atual.");}catch(RuntimeException error){status.setText("Não foi possível preparar o modelo agora.");}}).setNegativeButton("Cancelar",null).show();}
 private void showJob(){android.content.SharedPreferences p=getSharedPreferences("memory_job",0);job.setText(MemoryIndexService.running?MemoryIndexService.message:p.getBoolean("running",false)?"A análise anterior foi interrompida pelo Android. Solicite novamente; o índice anterior foi preservado.":p.getString("message","Processamento local sob demanda."));cancel.setVisibility(MemoryIndexService.running?View.VISIBLE:View.GONE);}
 private void search(){if(isDestroyed())return;final int ticket=++generation;String text=query.getText().toString();boolean only=favorites;status.setText("Buscando no índice local…");worker.execute(()->{try(MemoryStore store=new MemoryStore(this)){List<MemoryStore.Hit> found=store.search(text,only);main.post(()->{if(isDestroyed()||ticket!=generation)return;hits.clear();hits.addAll(found);List<String> labels=new ArrayList<>();for(MemoryStore.Hit hit:found)labels.add((hit.favorite?"★ ":"")+hit.source.name+" • "+location(hit)+"\n"+hit.text);results.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,labels){public View getView(int i,View recycled,ViewGroup parent){TextView v=(TextView)super.getView(i,recycled,parent);v.setTextColor(Ui.TEXT);v.setTextSize(14);v.setMaxLines(7);v.setEllipsize(android.text.TextUtils.TruncateAt.END);v.setPadding(Ui.dp(MemoryActivity.this,12),Ui.dp(MemoryActivity.this,12),Ui.dp(MemoryActivity.this,12),Ui.dp(MemoryActivity.this,12));Ui.card(v,false);return v;}});status.setText(found.size()+" trechos"+(only?" favoritos":"")+" • até 100 resultados; refine as palavras para ver outros.");});}catch(RuntimeException error){main.post(()->{if(!isDestroyed()&&ticket==generation)status.setText("Não foi possível consultar o índice. Aguarde a análise e tente novamente.");});}});}
 static String location(MemoryStore.Hit hit){return hit.page>=0?"página "+(hit.page+1):VideoLoop.time(hit.start)+" → "+VideoLoop.time(hit.end)+(hit.source.kind.equals("speech")||hit.source.kind.equals("audio")?" • aproximado":"");}
 private void options(MemoryStore.Hit hit){dialog=new AlertDialog.Builder(this).setTitle(location(hit)).setItems(new String[]{"Abrir no ponto encontrado",hit.favorite?"Remover dos favoritos":"Marcar favorito","Copiar texto","Compartilhar texto","Salvar áudio deste trecho em MP3"},(d,i)->{if(i==0)open(hit);else if(i==1)worker.execute(()->{try(MemoryStore s=new MemoryStore(this)){s.favorite(hit);}main.post(()->{if(!isDestroyed())search();});});else if(i==2){((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Trecho",hit.text));Toast.makeText(this,"Texto copiado",Toast.LENGTH_SHORT).show();}else if(i==3){Intent send=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,hit.source.name+" • "+location(hit)+"\n"+hit.text);startActivity(Intent.createChooser(send,"Compartilhar trecho de texto"));}else if(hit.page>=0)Toast.makeText(this,"PDF não contém uma faixa de áudio para recortar",Toast.LENGTH_LONG).show();else validate(hit,()->startActivity(new Intent(this,ChapterExportActivity.class).putExtra("source",hit.source.uri).putExtra("stamp",hit.source.stamp).putExtra("name",hit.source.name+" - trecho").putExtra("start",hit.start).putExtra("end",hit.end).putExtra("duration",hit.end).putExtra("memory_tag",hit.tag)));}).setNegativeButton("Fechar",null).show();}
 private void validate(MemoryStore.Hit hit,Runnable action){worker.execute(()->{boolean valid=hit.source.stamp.equals(AudioChapterStore.stamp(this,Uri.parse(hit.source.uri)));main.post(()->{if(isDestroyed())return;if(valid)action.run();else status.setText("O arquivo mudou ou perdeu acesso. Reindexe-o em Arquivos lembrados.");});});}
 private void open(MemoryStore.Hit hit){validate(hit,()->{Class<?> screen=hit.page>=0?PdfActivity.class:("audio".equals(hit.source.kind)||"subtitle_audio".equals(hit.source.kind))?MainActivity.class:VideoActivity.class;Intent i=new Intent(this,screen).setAction(Intent.ACTION_VIEW).setDataAndType(Uri.parse(hit.source.uri),hit.page>=0?"application/pdf":screen==MainActivity.class?"audio/*":"video/*").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION).putExtra("onda_start_ms",hit.start).putExtra("onda_page",hit.page);try{startActivity(i);}catch(RuntimeException error){status.setText("Abra o arquivo novamente pelo Android para conceder acesso.");}});}
 private void sources(){worker.execute(()->{try(MemoryStore s=new MemoryStore(this)){List<MemoryStore.Source> sources=s.sources();main.post(()->{if(isDestroyed())return;String[] names=new String[sources.size()];for(int i=0;i<names.length;i++)names[i]=sources.get(i).name+" • "+("pdf".equals(sources.get(i).kind)?"PDF":sources.get(i).sidecar.isEmpty()?"Transcrição":"Legenda");dialog=new AlertDialog.Builder(this).setTitle("Arquivos lembrados • "+names.length).setItems(names,(d,i)->sourceOptions(sources.get(i))).setNegativeButton("Fechar",null).show();});}});}
