 protected void onStart(){super.onStart();started=true;MemoryIndexService.listen(listener);showJob();}protected void onStop(){started=false;MemoryIndexService.forget(listener);super.onStop();}protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("query",query.getText().toString());out.putBoolean("favorites",favorites);if(owner!=null)out.putString("owner",owner.toString());out.putString("ownerName",ownerName);}protected void onDestroy(){generation++;if(dialog!=null)dialog.dismiss();worker.shutdownNow();super.onDestroy();}
